import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, texture, normalMap, displacementMap } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  // ─────────────────────────────────────────────────────────────
  // STATE & CLEANUP
  // ─────────────────────────────────────────────────────────────
  const state = {
    timelines: [],
    resourceCleanups: [],
    primitiveCleanups: [],
  };

  group.userData.cleanup = () => {
    state.timelines.forEach((tl) => tl.kill());
    state.resourceCleanups.forEach((fn) => fn());
    state.primitiveCleanups.forEach((fn) => fn());
  };

  // ─────────────────────────────────────────────────────────────
  // MATERIAL: Displacement + Hero Grade PBR
  // ─────────────────────────────────────────────────────────────
  const createMaterial = async () => {
    // Load textures
    const colorTex = await ctx.textureLoader.loadTexture(config.imageUrl);
    const depthTex = await ctx.textureLoader.loadTexture(config.depthMapUrl);

    // TSL displacement intensity uniform
    const displacementIntensity = uniform(0.08);

    // Displacement: sample depth map, remap to [-1, 1], apply intensity
    const displacementNode = mix(
      vec3(0),
      texture(depthTex).x.mul(displacementIntensity).mul(2).sub(displacementIntensity),
      smoothstep(0, 1, texture(depthTex).x)
    );

    // Hero-grade PBR: machined metal aesthetic
    const material = new MeshStandardNodeMaterial({
      colorNode: texture(colorTex),
      metalness: 0.45,
      roughness: 0.55,
      clearcoat: 0.18,
      clearcoatRoughness: 0.4,
      displacementNode,
      displacementScale: 0.12,
    });

    state.resourceCleanups.push(() => {
      colorTex.dispose();
      depthTex.dispose();
      material.dispose();
    });

    return material;
  };

  // ─────────────────────────────────────────────────────────────
  // GEOMETRY: Tessellated Plane for Displacement
  // ─────────────────────────────────────────────────────────────
  const geometry = new THREE.PlaneGeometry(2.4, 1.5, 64, 64);
  state.resourceCleanups.push(() => geometry.dispose());

  // ─────────────────────────────────────────────────────────────
  // BUILD MESH
  // ─────────────────────────────────────────────────────────────
  createMaterial().then((material) => {
    const mesh = new THREE.Mesh(geometry, material);
    mesh.position.z = 0;
    group.add(mesh);

    // Store mesh reference for event handlers
    group.userData.mesh = mesh;
  });

  // ─────────────────────────────────────────────────────────────
  // LIGHTING: Accent Rim Light (hero-grade)
  // ─────────────────────────────────────────────────────────────
  const rimLight = new THREE.DirectionalLight(0xff2a38, 0.75);
  rimLight.position.set(-2, 1.5, 1.8);
  group.add(rimLight);

  const fillLight = new THREE.DirectionalLight(0xffffff, 0.35);
  fillLight.position.set(1, -0.5, 2);
  group.add(fillLight);

  // ─────────────────────────────────────────────────────────────
  // CINEMATIC PRIMITIVES
  // ─────────────────────────────────────────────────────────────

  // 1. Parallax-scroll (trigger: scroll, intensity 0.4)
  if (config.cinematicPrimitives?.some((p) => p.name === 'parallax-scroll')) {
    const parallaxResult = ctx.primitives['parallax-scroll'](group, { intensity: 0.4 });
    if (parallaxResult?.cleanup) {
      state.primitiveCleanups.push(parallaxResult.cleanup);
    }
  }

  // 2. Depth-rotate (trigger: hover, maxDeg 8)
  if (config.cinematicPrimitives?.some((p) => p.name === 'depth-rotate')) {
    const depthRotateResult = ctx.primitives['depth-rotate'](group, { maxDeg: 8 });
    if (depthRotateResult?.cleanup) {
      state.primitiveCleanups.push(depthRotateResult.cleanup);
    }
  }

  // ─────────────────────────────────────────────────────────────
  // INTERACTION HANDLERS
  // ─────────────────────────────────────────────────────────────
  group.userData.handlers = {};

  // Hover: rise-in entrance (subtle 0.15 scene units)
  group.userData.handlers.onHoverEnter = () => {
    const tl = gsap.timeline();
    tl.to(
      group.position,
      {
        y: '-=0.15',
        duration: 0.7,
        ease: 'power3.out',
      },
      0
    );
    state.timelines.push(tl);
  };

  group.userData.handlers.onHoverExit = () => {
    const tl = gsap.timeline();
    tl.to(
      group.position,
      {
        y: '+=0.15',
        duration: 0.9,
        ease: 'power4.out',
        overwrite: 'auto',
      },
      0
    );
    state.timelines.push(tl);
  };

  // Click: emit hub-home.select
  group.userData.handlers.onClick = () => {
    ctx.emit('navigate', { to: 'hub-home' });
  };

  // ─────────────────────────────────────────────────────────────
  // INITIAL ENTRANCE: Weighted settle (overshoot 1.04 -> 1.0)
  // ─────────────────────────────────────────────────────────────
  group.scale.set(1.04, 1.04, 1.04);
  group.position.y += 0.2; // Start offset for fade-up feel

  const entranceTimeline = gsap.timeline();
  entranceTimeline
    .to(
      group.scale,
      {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.9,
        ease: 'power4.out',
      },
      0
    )
    .to(
      group.position,
      {
        y: '-=0.2',
        duration: 0.7,
        ease: 'power3.out',
      },
      0
    );

  state.timelines.push(entranceTimeline);

  // ─────────────────────────────────────────────────────────────
  // CONTACT SHADOW (grounded presence)
  // ─────────────────────────────────────────────────────────────
  const shadowPlane = new THREE.Mesh(
    new THREE.CircleGeometry(1.4, 32),
    new THREE.MeshBasicMaterial({
      color: 0x000000,
      transparent: true,
      opacity: 0.45,
      depthWrite: false,
    })
  );
  shadowPlane.position.z = -0.05;
  shadowPlane.rotation.x = Math.PI / 2;
  group.add(shadowPlane);

  state.resourceCleanups.push(() => {
    shadowPlane.geometry.dispose();
    shadowPlane.material.dispose();
  });

  // ─────────────────────────────────────────────────────────────
  // RETURN
  // ─────────────────────────────────────────────────────────────
  return group;
}
